create or replace function public.layer2_provider_trial_record(p_trial_course_id uuid,p_acquisition_provider_id uuid,p_domain_key text,p_provider_attempt_id uuid default null,p_acquisition_success boolean default null,p_gatekeeping_bypassed boolean default null,p_javascript_rendered boolean default null,p_evidence_quality_score numeric default null,p_deterministic_extraction_success boolean default null,p_correctness_status text default 'unverified',p_latency_ms integer default null,p_request_count integer default 1,p_vendor_cost_usd numeric default null,p_fields_targeted integer default 0,p_fields_resolved integer default 0,p_layer3_required boolean default false,p_layer4_required boolean default false,p_blocker text default null,p_metrics jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,pipeline as $$ declare v_trial uuid; v_id uuid; begin if auth.role()<>'service_role' then raise exception 'service_role required'; end if; select trial_id into v_trial from pipeline.layer2_completeness_trial_courses where id=p_trial_course_id; if v_trial is null then raise exception 'trial course not found'; end if; insert into pipeline.layer2_provider_trial_results(trial_id,trial_course_id,acquisition_provider_id,provider_attempt_id,domain_key,acquisition_success,gatekeeping_bypassed,javascript_rendered,evidence_quality_score,deterministic_extraction_success,correctness_status,latency_ms,request_count,vendor_cost_usd,fields_targeted,fields_resolved,layer3_required,layer4_required,blocker,metrics) values(v_trial,p_trial_course_id,p_acquisition_provider_id,p_provider_attempt_id,p_domain_key,p_acquisition_success,p_gatekeeping_bypassed,p_javascript_rendered,p_evidence_quality_score,p_deterministic_extraction_success,p_correctness_status,p_latency_ms,coalesce(p_request_count,1),p_vendor_cost_usd,coalesce(p_fields_targeted,0),coalesce(p_fields_resolved,0),coalesce(p_layer3_required,false),coalesce(p_layer4_required,false),p_blocker,coalesce(p_metrics,'{}'::jsonb)) returning id into v_id; return v_id; end $$;
revoke all on function public.layer2_provider_trial_record(uuid,uuid,text,uuid,boolean,boolean,boolean,numeric,boolean,text,integer,integer,numeric,integer,integer,boolean,boolean,text,jsonb) from public,anon,authenticated; grant execute on function public.layer2_provider_trial_record(uuid,uuid,text,uuid,boolean,boolean,boolean,numeric,boolean,text,integer,integer,numeric,integer,integer,boolean,boolean,text,jsonb) to service_role;
create or replace function pipeline.layer2_provider_trial_summary(p_trial_id uuid) returns jsonb language sql stable security definer set search_path=pipeline as $$ select coalesce(jsonb_agg(x order by (x->>'cost_per_resolved_field_usd')::numeric nulls last,(x->>'resolution_rate')::numeric desc),'[]'::jsonb) from (select jsonb_build_object('provider_id',r.acquisition_provider_id,'provider_key',max(ap.provider_key),'attempted_rows',count(*),'acquisition_success_rate',round((count(*) filter(where r.acquisition_success is true))::numeric/nullif(count(*),0),4),'deterministic_success_rate',round((count(*) filter(where r.deterministic_extraction_success is true))::numeric/nullif(count(*),0),4),'correct_rate',round((count(*) filter(where r.correctness_status='correct'))::numeric/nullif(count(*) filter(where r.correctness_status in ('correct','incorrect')),0),4),'fields_targeted',sum(r.fields_targeted),'fields_resolved',sum(r.fields_resolved),'resolution_rate',round(sum(r.fields_resolved)::numeric/nullif(sum(r.fields_targeted),0),4),'vendor_cost_usd',sum(coalesce(r.vendor_cost_usd,0)),'cost_per_resolved_field_usd',round(sum(coalesce(r.vendor_cost_usd,0))/nullif(sum(r.fields_resolved),0),6),'avg_latency_ms',round(avg(r.latency_ms) filter(where r.latency_ms is not null),1),'layer3_escalation_rate',round((count(*) filter(where r.layer3_required))::numeric/nullif(count(*),0),4),'layer4_escalation_rate',round((count(*) filter(where r.layer4_required))::numeric/nullif(count(*),0),4),'avg_evidence_quality',round(avg(r.evidence_quality_score),4)) x from pipeline.layer2_provider_trial_results r join pipeline.layer2_acquisition_providers ap on ap.id=r.acquisition_provider_id where r.trial_id=p_trial_id group by r.acquisition_provider_id) s $$;
revoke all on function pipeline.layer2_provider_trial_summary(uuid) from public,anon,authenticated; grant execute on function pipeline.layer2_provider_trial_summary(uuid) to service_role;
create or replace function public.layer2_completeness_trial_finalize(p_trial_id uuid) returns jsonb language plpgsql security definer set search_path=public,pipeline as $$ declare v_summary jsonb; v_result jsonb; begin if auth.role()<>'service_role' then raise exception 'service_role required'; end if; select pipeline.layer2_provider_trial_summary(p_trial_id) into v_summary; select jsonb_build_object('course_count',count(*),'resolved',count(*) filter(where status='resolved'),'layer3_required',count(*) filter(where status='layer3_required'),'layer4_required',count(*) filter(where status='layer4_required'),'blocked',count(*) filter(where status='blocked'),'provider_summary',v_summary) into v_result from pipeline.layer2_completeness_trial_courses where trial_id=p_trial_id; update pipeline.layer2_completeness_trials set status=case when exists(select 1 from pipeline.layer2_completeness_trial_courses where trial_id=p_trial_id and status in ('selected','acquiring')) then 'blocked' else 'completed' end,result_summary=v_result,completed_at=now() where id=p_trial_id; return v_result; end $$;
revoke all on function public.layer2_completeness_trial_finalize(uuid) from public,anon,authenticated; grant execute on function public.layer2_completeness_trial_finalize(uuid) to service_role;
